 static void setup(ServerLevel l){aura(l);pool(l,P.south(7).west(6),TaintContent.DEATH.block.get().defaultBlockState());pool(l,P.south(7),Blocks.WATER.defaultBlockState());for(var q:BlockPos.betweenClosed(P.south(7).offset(-1,0,-1),P.south(7).offset(1,0,1)))put(l,q,Blocks.WATER.defaultBlockState());pool(l,P.south(7).east(6),TaintContent.GOO.get().defaultBlockState());salts=new ItemEntity(l,P.getX()+.5,P.getY()+.1,P.getZ()+7.5,new ItemStack(TaintContent.SALTS.get(),2));salts.setDeltaMovement(Vec3.ZERO);salts.setPickUpDelay(10000);l.addFreshEntity(salts);due=l.getGameTime()+240;stage=2;}
 static void gallery(ServerLevel l){for(var q:BlockPos.betweenClosed(P.offset(-8,-1,-5),P.offset(8,-1,2)))put(l,q,TaintWorld.state("taint_soil"));seed=TaintWorld.spawnSeed(l,P,false,0);check(seed!=null,"Gallery seed failed");seed.setNoAi(true);seed.boost=37;for(int i=-6;i<=6;i+=2){var p=P.offset(i,0,-3);var f=(TaintBlock.Fibre)TaintContent.BLOCKS.get("taint_fibre").get();put(l,p,f.connections(l,p,f.defaultBlockState()));}put(l,P.west(4),TaintWorld.state("taint_rock"));put(l,P.east(4),TaintWorld.state("taint_log"));put(l,P.east(4).above(),TaintWorld.state("taint_feature"));var t=TaintedMob.spawn(l,TaintedMob.Kind.TENTACLE,P.west(6));if(t!=null)t.setNoAi(true);var slime=new ThaumicSlime(TaintContent.SLIME.get(),l);slime.setSize(2,true);slime.setNoAi(true);slime.setPos(Vec3.atBottomCenterOf(P.east(7)));l.addFreshEntity(slime);pool(l,P.south(7).east(6),TaintContent.GOO.get().defaultBlockState());for(var q:BlockPos.betweenClosed(P.south(7).offset(-1,0,-1),P.south(7).offset(1,0,1)))put(l,q,TaintContent.PURE.block.get().defaultBlockState());
  if(!l.getServer().isDedicatedServer()){actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+12.5,P.getY()+8,P.getZ()+18.5,Set.of(),145,25,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();actor.getInventory().clearContent();actor.getInventory().setSelectedSlot(0);actor.getInventory().add(new ItemStack(TaintContent.DEATH.bucket.get()));actor.getInventory().add(new ItemStack(TaintContent.PURE.bucket.get()));l.getServer().getCommands().performPrefixedCommand(l.getServer().createCommandSourceStack(),"time set day");ready=true;stage=4;Thaumcraft.LOGGER.info("TAINT_CLIENT_OK: actual corrupted patch with seed and tendril, three physical fluid basins and salts-paid purifier");}
  else{stage=4;Thaumcraft.LOGGER.info("TAINT_WRITE_OK: native fluid sources, corrupted terrain and persistent seed saved");l.getServer().halt(false);}}
